import{_ as r,o as a,c as l,am as o}from"./chunks/framework.DcVeWzII.js";const c=JSON.parse('{"title":"特征选择 vs 数据降维：区别与联系","description":"","frontmatter":{},"headers":[],"relativePath":"Y3S1/AIML/特征选择vs降维区别.md","filePath":"Y3S1/AIML/特征选择vs降维区别.md","lastUpdated":1773393631000}'),n={name:"Y3S1/AIML/特征选择vs降维区别.md"};function s(e,t,i,d,g,h){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="特征选择-vs-数据降维-区别与联系" tabindex="-1">特征选择 vs 数据降维：区别与联系 <a class="header-anchor" href="#特征选择-vs-数据降维-区别与联系" aria-label="Permalink to “特征选择 vs 数据降维：区别与联系”">​</a></h1><blockquote><p>基于 ML Lecture 4 Part I &amp; Part II 内容整理</p></blockquote><h2 id="一、核心区别" tabindex="-1">一、核心区别 <a class="header-anchor" href="#一、核心区别" aria-label="Permalink to “一、核心区别”">​</a></h2><h3 id="_1-基本定义" tabindex="-1">1. 基本定义 <a class="header-anchor" href="#_1-基本定义" aria-label="Permalink to “1. 基本定义”">​</a></h3><table tabindex="0"><thead><tr><th>方面</th><th>特征选择 (Feature Selection)</th><th>数据降维 (Dimension Reduction)</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>从原始数据集中<strong>识别并选择</strong>最相关、信息量最大且非冗余特征（变量）子集的过程，<strong>直接丢弃</strong>无关或嘈杂的特征</td><td>利用数学或统计方法将高维数据<strong>转换为低维表示</strong>，通过<strong>特征组合/转换</strong>创建新特征</td></tr><tr><td><strong>操作方式</strong></td><td><strong>直接丢弃</strong>原始特征</td><td><strong>转换/组合</strong>原始特征，创建新特征</td></tr><tr><td><strong>保留的特征</strong></td><td>保留原始特征集中的<strong>子集</strong>（仍然是原始特征）</td><td>创建<strong>新的特征</strong>（通常是原始特征的线性或非线性组合）</td></tr></tbody></table><h3 id="_2-关键区别总结" tabindex="-1">2. 关键区别总结 <a class="header-anchor" href="#_2-关键区别总结" aria-label="Permalink to “2. 关键区别总结”">​</a></h3><p><strong>特征选择</strong>：</p><ul><li>✅ <strong>保留原始特征</strong>：选出的特征仍然是原始特征集中的一部分</li><li>✅ <strong>可解释性强</strong>：保留的是原始特征，含义清晰（如&quot;年龄&quot;、&quot;收入&quot;）</li><li>✅ <strong>直接丢弃</strong>：不重要的特征直接被移除</li><li>⚠️ <strong>局限性</strong>：如果所有特征都重要，直接丢弃会导致性能下降</li></ul><p><strong>数据降维</strong>：</p><ul><li>✅ <strong>创建新特征</strong>：通过数学变换创建新的特征（如PCA的主成分）</li><li>✅ <strong>特征组合</strong>：新特征通常是原始特征的线性或非线性组合</li><li>✅ <strong>保留信息</strong>：即使所有原始特征都重要，也可以通过组合保留信息</li><li>⚠️ <strong>可解释性降低</strong>：新特征的含义可能不如原始特征直观（如&quot;主成分1&quot;、&quot;主成分2&quot;）</li></ul><h2 id="二、具体方法对比" tabindex="-1">二、具体方法对比 <a class="header-anchor" href="#二、具体方法对比" aria-label="Permalink to “二、具体方法对比”">​</a></h2><h3 id="特征选择方法-lecture-4-part-i" tabindex="-1">特征选择方法（Lecture 4 Part I） <a class="header-anchor" href="#特征选择方法-lecture-4-part-i" aria-label="Permalink to “特征选择方法（Lecture 4 Part I）”">​</a></h3><table tabindex="0"><thead><tr><th>方法类型</th><th>代表方法</th><th>特点</th></tr></thead><tbody><tr><td><strong>过滤法 (Filter)</strong></td><td>方差阈值法、卡方检验、F检验、互信息法</td><td>基于统计特性，模型无关，速度快</td></tr><tr><td><strong>包裹法 (Wrapper)</strong></td><td>前向选择、后向消除、递归特征消除 (RFE)</td><td>基于模型性能，计算成本高，但更准确</td></tr><tr><td><strong>嵌入法 (Embedded)</strong></td><td>L1正则化、决策树特征重要性</td><td>在模型训练过程中同时完成特征选择</td></tr></tbody></table><h3 id="降维方法-lecture-4-part-ii" tabindex="-1">降维方法（Lecture 4 Part II） <a class="header-anchor" href="#降维方法-lecture-4-part-ii" aria-label="Permalink to “降维方法（Lecture 4 Part II）”">​</a></h3><table tabindex="0"><thead><tr><th>方法类型</th><th>代表方法</th><th>特点</th></tr></thead><tbody><tr><td><strong>线性降维</strong></td><td>PCA、LDA、SVD</td><td>通过线性变换创建新特征</td></tr><tr><td><strong>非线性降维</strong></td><td>核PCA、LLE、t-SNE、VAE</td><td>通过非线性变换创建新特征</td></tr></tbody></table><h2 id="三、应用场景对比" tabindex="-1">三、应用场景对比 <a class="header-anchor" href="#三、应用场景对比" aria-label="Permalink to “三、应用场景对比”">​</a></h2><h3 id="选择特征选择的情况" tabindex="-1">选择特征选择的情况 <a class="header-anchor" href="#选择特征选择的情况" aria-label="Permalink to “选择特征选择的情况”">​</a></h3><p>✅ <strong>需要保留原始特征含义</strong></p><ul><li>医疗诊断：医生需要知道哪些具体指标（如&quot;血压&quot;、&quot;血糖&quot;）最重要</li><li>特征可解释性要求高的场景</li></ul><p>✅ <strong>特征数量适中</strong></p><ul><li>特征数量不是特别多，可以直接筛选</li></ul><p>✅ <strong>需要快速筛选</strong></p><ul><li>使用过滤法可以快速筛选特征</li></ul><h3 id="选择数据降维的情况" tabindex="-1">选择数据降维的情况 <a class="header-anchor" href="#选择数据降维的情况" aria-label="Permalink to “选择数据降维的情况”">​</a></h3><p>✅ <strong>所有特征都重要，但维度太高</strong></p><ul><li>如果直接丢弃特征会导致信息损失</li><li>需要通过组合保留所有特征的信息</li></ul><p>✅ <strong>需要缓解&quot;维数灾难&quot;</strong></p><ul><li>特征数量远大于样本数量</li><li>数据在高维空间中过于稀疏</li></ul><p>✅ <strong>需要可视化</strong></p><ul><li>将数据降至2D/3D进行可视化分析</li></ul><p>✅ <strong>计算效率优先</strong></p><ul><li>降维后可以显著提高后续模型训练效率</li></ul><h2 id="四、为什么分成两个-lecture-讲解" tabindex="-1">四、为什么分成两个 Lecture 讲解？ <a class="header-anchor" href="#四、为什么分成两个-lecture-讲解" aria-label="Permalink to “四、为什么分成两个 Lecture 讲解？”">​</a></h2><h3 id="_1-方法本质不同" tabindex="-1">1. <strong>方法本质不同</strong> <a class="header-anchor" href="#_1-方法本质不同" aria-label="Permalink to “1. 方法本质不同”">​</a></h3><ul><li><strong>特征选择</strong>：关注的是<strong>选择哪些原始特征</strong>，方法包括统计检验、模型性能评估等</li><li><strong>数据降维</strong>：关注的是<strong>如何转换/组合特征</strong>，方法包括矩阵分解、线性变换等</li></ul><h3 id="_2-数学基础不同" tabindex="-1">2. <strong>数学基础不同</strong> <a class="header-anchor" href="#_2-数学基础不同" aria-label="Permalink to “2. 数学基础不同”">​</a></h3><ul><li><p><strong>特征选择</strong>：</p><ul><li>统计学方法（卡方检验、F检验、互信息）</li><li>模型训练与评估</li><li>正则化理论（L1正则化）</li></ul></li><li><p><strong>数据降维</strong>：</p><ul><li>线性代数（特征分解、奇异值分解）</li><li>矩阵理论（协方差矩阵、散度矩阵）</li><li>优化理论（最大化方差、最大化类间可分性）</li></ul></li></ul><h3 id="_3-应用场景不同" tabindex="-1">3. <strong>应用场景不同</strong> <a class="header-anchor" href="#_3-应用场景不同" aria-label="Permalink to “3. 应用场景不同”">​</a></h3><ul><li><strong>特征选择</strong>：更注重<strong>可解释性</strong>和<strong>特征重要性分析</strong></li><li><strong>数据降维</strong>：更注重<strong>信息保留</strong>和<strong>计算效率</strong></li></ul><h3 id="_4-教学逻辑" tabindex="-1">4. <strong>教学逻辑</strong> <a class="header-anchor" href="#_4-教学逻辑" aria-label="Permalink to “4. 教学逻辑”">​</a></h3><ul><li><p><strong>Part I（特征选择）</strong>：从简单到复杂</p><ul><li>过滤法（最简单，基于统计）</li><li>包裹法（中等复杂度，需要训练模型）</li><li>嵌入法（在训练中完成，最复杂）</li></ul></li><li><p><strong>Part II（降维）</strong>：从线性到非线性</p><ul><li>线性降维（PCA、LDA、SVD）</li><li>非线性降维（核方法、流形学习等）</li></ul></li></ul><h3 id="_5-知识体系完整性" tabindex="-1">5. <strong>知识体系完整性</strong> <a class="header-anchor" href="#_5-知识体系完整性" aria-label="Permalink to “5. 知识体系完整性”">​</a></h3><p>分开讲解可以：</p><ul><li>✅ 更深入地讲解每种方法的原理和细节</li><li>✅ 避免概念混淆（特征选择 vs 特征转换）</li><li>✅ 便于学生理解两种不同的解决思路</li><li>✅ 为后续选择合适方法提供清晰指导</li></ul><h2 id="五、两者的联系" tabindex="-1">五、两者的联系 <a class="header-anchor" href="#五、两者的联系" aria-label="Permalink to “五、两者的联系”">​</a></h2><p>虽然方法不同，但<strong>目标一致</strong>：</p><ul><li>🎯 减少特征数量</li><li>🎯 提高模型性能</li><li>🎯 降低计算成本</li><li>🎯 提高泛化能力</li></ul><p><strong>实际应用中</strong>：</p><ul><li>可以<strong>先进行特征选择</strong>（去除明显无关的特征）</li><li>然后<strong>再进行降维</strong>（对剩余的重要特征进行组合/转换）</li><li>或者<strong>直接使用降维</strong>（如果所有特征都重要）</li></ul><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to “六、总结”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>特征选择</th><th>数据降维</th></tr></thead><tbody><tr><td><strong>核心操作</strong></td><td>直接丢弃特征</td><td>转换/组合特征</td></tr><tr><td><strong>保留内容</strong></td><td>原始特征的子集</td><td>新创建的特征</td></tr><tr><td><strong>可解释性</strong></td><td>高（保留原始特征）</td><td>低（新特征含义不直观）</td></tr><tr><td><strong>适用情况</strong></td><td>有明显无关特征</td><td>所有特征都重要但维度高</td></tr><tr><td><strong>数学基础</strong></td><td>统计学、模型评估</td><td>线性代数、矩阵分解</td></tr><tr><td><strong>主要方法</strong></td><td>过滤法、包裹法、嵌入法</td><td>PCA、LDA、SVD等</td></tr></tbody></table><p><strong>关键理解</strong>：</p><blockquote><p>特征选择是&quot;<strong>选哪些</strong>&quot;，降维是&quot;<strong>怎么变</strong>&quot;。</p><p>如果特征明显不重要 → 用特征选择直接丢弃</p><p>如果所有特征都重要但维度太高 → 用降维进行组合/转换</p></blockquote>',53)])])}const b=r(n,[["render",s]]);export{c as __pageData,b as default};
